@import "../css/constant.scss";
@import "../css/function.scss";

.main-card {
  @include marginItem();
  box-sizing: border-box;
  overflow: hidden;
  background-color: $bg-color;
  height: 100vh;
}

.parent-container {
  height: $viewheight;
  overflow: hidden;
  @include flexColumn();
  margin-left: $sidebar-fullhd-width;
  background-size: cover;
  background-repeat: no-repeat;
  background-position: center;
}

.banner-container {
  width: 100%;
  height: $banner-fullhd-height;
  @include flexColumn();
  z-index: 1;
}

.banner-container-zero {
  width: 100%;
  height: 0;
  @include flexColumn();
  z-index: 1;
}

.content-container-zero {
  overflow: hidden;
  height: 100%;
  scroll-behavior: smooth;
  z-index: 3;
}

.banner-container-zero:last-child {
  margin-bottom: 300px;
}

.content-container {
  overflow: hidden;
  height: 52vh;
  scroll-behavior: smooth;
  z-index: 3;
}

// .content-container:last-child {
//   padding-bottom: 700px;
// }
.content-container-zero:last-child {
  padding-bottom: 700px !important;
}

.content-container :last-child {
  margin-bottom: 700px !important;
}

.background-container {
  height: $poster-fullhd-height;
  width: $poster-fullhd-width;
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: $poster-left;
  z-index: 0;
  background-position: center center;
  background-size: cover;
  border-style: solid;
  border-width: 0px 0px 5px 5px;
  border-color: $bg-color;
}

.poster-fullscreen {
  height: 100vh;
  width: 100vw;
  background-repeat: no-repeat;
  // background-size: cover;
  // background-position: left;
  //   z-index: -1;

  transition: background-image 0.5s ease-in-out;
  background-position: 0% 0%;
  background-size: 100% 100%;
}

.poster2 {
  // position: ;
  height: 100%;
  width: 100%;
  background-repeat: no-repeat;
  // background-size: cover;
  // background-position: left;
  //   z-index: -1;

  transition: background-image 0.5s ease-in-out;
  background-position: 0% 0%;
  background-size: 100% 100%;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-image: url("data:image/png;base64,");
}

.poster {
  position: absolute;
  height: 100%;
  width: 100%;
  background-repeat: no-repeat;
  // background-size: cover;
  // background-position: left;
  //   z-index: -1;

  transition: background-image 0.5s ease-in-out;
  background-position: 0% 0%;
  background-size: 100% 100%;
}

.banner-title,
banner-title:lang(te) {
  @include h1_fullhd_display_title();
  color: $row-title-color;
  font-family: $font-family-bold;
  z-index: 5;
  @include marginItem(0, 0, 3, 0);
  margin-top: $banner-fullhd-title-margintop;
  overflow: hidden;
  word-wrap: break-word;
  width: 50%;
  white-space: normal;
  position: relative;
}


.banner-description {
  @include h4_fullhd_display_title();
  // @include paddingItem(0, 0, 0, 0);
  // color: $display-description-color;
  // font-size:27px;
  // letter-spacing: 1.09px;
  // color: #C2C4C6;
  // max-height: 5em; /* Set the maximum height to show five lines */
  // overflow: hidden;
  // position: relative; /* Create a stacking context */
  // line-height: 1.2em; /* Set line height to control the number of lines displayed */
